function home(){return `<main><section class="hero"><div class="container hero-inner"><div class="hero-copy"><div class="eyebrow">Dubai moves, thoughtfully handled</div><h1>Relocation <em>simplified</em></h1><p>From the first box to the last detail, we bring a little more care and a lot more clarity to your next move.</p><div class="hero-actions"><a class="btn" href="/quote">Get your free quote ${svgArrow}</a><a class="btn outline" href="/services">Explore our services <span>↓</span></a></div><div class="hero-contact-links"><a class="hero-contact-link" href="${biz.whatsapp?`https://wa.me/${biz.whatsapp}`:'/contact'}" target="${biz.whatsapp?'_blank':'_self'}" rel="noopener noreferrer" aria-label="WhatsApp"><span class="hero-contact-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.5 11.7a8.4 8.4 0 0 1-12.4 7.4L3 20l.9-4.9a8.4 8.4 0 1 1 16.6-3.4Z"/><path d="M8.8 8.2c.3-.6.6-.6 1-.6h.4c.2 0 .4.1.5.4l.7 1.7c.1.2.1.4-.1.6l-.6.7c-.2.2-.2.4-.1.6.6 1 1.4 1.8 2.5 2.3.2.1.4.1.6-.1l.8-.9c.2-.2.4-.3.7-.2l1.6.8c.3.1.4.3.4.5 0 .5-.2 1.2-.7 1.6-.5.5-1.2.7-1.9.6-1-.1-2.3-.7-3.5-1.7-1.6-1.3-2.7-2.9-3-4.1-.3-1 .2-1.8.7-2.2Z"/></svg></span><span><b>WhatsApp</b><small>Chat with us</small></span></a><a class="hero-contact-link" href="${biz.phoneLink?`tel:${biz.phoneLink}`:'/contact'}" aria-label="Telephone"><span class="hero-contact-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5.2 3.5h3.2l1.5 4-2 1.7a16 16 0 0 0 6.9 6.9l1.7-2 4 1.5v3.2c0 1-.8 1.8-1.8 1.8C10 20.6 3.4 14 3.4 5.3c0-1 .8-1.8 1.8-1.8Z"/></svg></span><span><b>Telephone</b><small>Call the team</small></span></a><a class="hero-contact-link" href="${biz.email.includes('[')?'/contact':`mailto:${biz.email}`}" aria-label="Email"><span class="hero-contact-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="1.5"/><path d="m4 7 8 6 8-6"/></svg></span><span><b>Email</b><small>Send a message</small></span></a></div></div></div></section><section class="trustline"><div class="container"><div class="trust-item"><span class="trust-icon">✳</span>Thoughtful planning</div><i class="trust-sep"></i><div class="trust-item"><span class="trust-icon">◇</span>Careful handling</div><i class="trust-sep"></i><div class="trust-item"><span class="trust-icon">↗</span>Clear communication</div><i class="trust-sep"></i><div class="trust-item"><span class="trust-icon">◷</span>Flexible scheduling</div></div></section><section class="section"><div class="container"><div class="intro-grid"><div class="image-stack"><img src="${images.home}" alt="A mover carrying furniture beside a moving truck at an apartment building" loading="lazy"><div class="image-quote">“The details make all the difference.”<small>The KI Movers approach</small></div></div><div class="split-copy"><div class="eyebrow">A little about us</div><h2>Good moves begin with good people.</h2><p>A move is more than a change of address. It is a collection of beginnings, memories and everyday things that make a place feel like yours. We plan every transition around the people at its heart.</p><p>Our team brings together practical planning, careful handling and thoughtful communication to help you feel at home sooner.</p><div class="check-list"><span>One clear moving plan</span><span>Care for the little details</span><span>Support from first call</span><span>Flexible service options</span></div><a class="btn dark" href="/about">Get to know us ${svgArrow}</a></div></div></div></section><section class="section services-section" id="services"><div class="container"><div class="section-head"><div><div class="eyebrow">Ways we can help</div><h2>Move, your way.</h2></div><div><p>Every move has its own rhythm. Choose the support that fits yours, from one special piece to a full home or workplace.</p><a class="text-link" href="/services" style="margin-top:19px">View all services ${svgArrow}</a></div></div><div class="service-grid"><div class="featured-services-row">${serviceCard(services[0],0)}${serviceCard(services[2],2)}${serviceCard(services[3],3)}</div><div class="service-card wide"><span class="service-num">THE KI MOVERS WAY</span><span class="service-symbol">✳</span><h3>Every move deserves a little more thought.</h3><p>Tell us what matters most. We’ll shape the moving plan around you.</p><a href="/quote" class="text-link">Let’s talk about your move ${svgArrow}</a></div>${serviceCard(services[6],6)}</div></div></section><section class="section process" id="process"><div class="container"><div class="section-head"><div><div class="eyebrow">A clear way forward</div><h2>From first hello to home.</h2></div><p>Good preparation makes moving day feel lighter. Here is how we keep each step clear.</p></div><div class="steps">${[['01','Tell us about your move','A few details help us understand what matters most.'],['02','We take a closer look','We discuss access, timing and the things that need special care.'],['03','Your plan takes shape','A clear outline of the moving support you need.'],['04','Moving day, handled','Careful packing, transport and updates as your move unfolds.'],['05','Settle in','We help with unpacking and the finishing touches you choose.']].map(x=>`<div class="step"><span class="step-count">${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</div></div></section><section class="section"><div class="container"><div class="why-grid"><div class="why-photo"><img src="${images.team}" alt="Relocation professionals coordinating a move" loading="lazy"><div class="why-label"><b>People first, every step.</b><span>Care is in the details.</span></div></div><div class="why-copy"><div class="eyebrow">Why KI Movers</div><h2>A little care goes a long way.</h2><p>The best moving experience feels well thought through, well communicated and genuinely personal. We keep your priorities at the centre of the plan.</p><div class="benefits">${[['01','Experienced professionals','A team that treats your belongings with respect.'],['02','Careful handling','Thoughtful preparation for the things you value.'],['03','Clear pricing','Understand the scope before you commit.'],['04','Flexible scheduling','Plan around your home, work and timing.'],['05','Professional packing','Materials and methods suited to the move.'],['06','Here when you need us','A real point of contact from start to finish.']].map(x=>`<div class="benefit"><i>${x[0]}</i><div><b>${x[1]}</b><small>${x[2]}</small></div></div>`).join('')}</div><a class="text-link" href="/about">A little more about our approach ${svgArrow}</a></div></div></div></section><section class="section gallery"><div class="container"><div class="section-head"><div><div class="eyebrow">A look at the journey</div><h2>Care in every corner.</h2></div><a class="text-link" href="/gallery">Explore the gallery ${svgArrow}</a></div><div class="gallery-grid">${galleryItems().slice(0,5)}</div></div></section><section class="section testimonial-section"><div class="container"><div class="section-head"><div><div class="eyebrow">Kind words from customers</div><h2>Good moves stay with you.</h2></div><div class="home-rating"><strong>4.81</strong><span> / 5.0 · 357 ratings</span></div></div><div class="home-review-grid">${reviews.slice(0,3).map((review,index)=>`<article class="home-review-card"><div class="home-review-top">${reviewStars(review.rating)}<span>0${index+1}</span></div><h3>${escapeHtml(review.title)}</h3><p>“${escapeHtml(review.comment)}”</p><div class="home-review-author"><span>${escapeHtml(review.name)}</span><small>${escapeHtml(review.service)} · ${escapeHtml(review.date)}</small></div></article>`).join('')}</div><a class="text-link all-reviews-link" href="/about#reviews">Explore all 52 reviews ${svgArrow}</a></div></section><section class="section areas-section"><div class="container areas-wrap"><div class="areas-intro"><div class="eyebrow">Across Dubai & the UAE</div><h2>Wherever home is next.</h2><p>From city apartments to quieter corners of the Emirates, share your route and we’ll confirm the details of your move.</p><a class="text-link" href="/areas">Explore all locations ${svgArrow}</a></div><div class="areas-list">${areas.slice(0,12).map(a=>`<a href="${areaPath(a)}">${a}<span>↗</span></a>`).join('')}</div></div></section><section class="cta-band"><div class="container"><div><h2>Ready for a fresh start?</h2><p>Tell us a little about your move. We’ll take it from there.</p></div><div class="cta-buttons"><a class="btn dark" href="/quote">Plan your move ${svgArrow}</a><a class="btn outline" href="/contact">Get in touch</a></div></div></section></main>`}
function galleryItems(){return [[images.pack,'Careful packing'],[images.truck,'On the way'],[images.interior,'A new beginning'],[images.office,'Workplace relocation'],[images.living,'Room to settle'],[images.apartment,'City living']].map(([src,label])=>`<button data-lightbox="${src}" aria-label="View ${label}"><img loading="lazy" src="${src}" alt="${label}"><span>${label}</span></button>`)}
function faqMarkup(){return faqs.map((f,i)=>`<div class="faq-item"><button class="faq-q" aria-expanded="false"><span>${f[0]}</span><b>＋</b></button><div class="faq-a">${f[1]}</div></div>`).join('')}
function reviewStars(rating){return `<span class="review-stars" role="img" aria-label="${rating} out of 5 stars">${'★'.repeat(rating)}<span class="review-stars-empty">${'☆'.repeat(5-rating)}</span></span>`}
function reviewsSection(){return `<section class="section reviews-section" id="reviews"><div class="container"><div class="reviews-heading"><div><div class="eyebrow">Kind words from customers</div><h2>Reviews from real moves.</h2><p>52 published customer reviews from the KI Movers ServiceMarket profile.</p></div><div class="rating-summary"><span class="rating-score">4.81<small> / 5.0</small></span><span class="aggregate-stars" role="img" aria-label="4.81 out of 5 stars">★★★★★</span><span class="rating-count">357 ratings on ServiceMarket</span><a class="review-source verified-source" href="https://servicemarket.com/service-provider/kashif-irshad" target="_blank" rel="noopener noreferrer"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3 19 6v5c0 4.5-3 8-7 10-4-2-7-5.5-7-10V6l7-3Z"/><path d="m9 12 2 2 4-4"/></svg>View verified profile ↗</a></div></div><div class="reviews-grid">${reviews.map((review,index)=>`<article class="review-card" style="--review-order:${index}"><div class="review-card-top">${reviewStars(review.rating)}<span class="review-service">${escapeHtml(review.service)}</span></div><h3>${escapeHtml(review.title)}</h3><div class="review-quote-mark" aria-hidden="true">“</div><p class="review-comment">${escapeHtml(review.comment)}</p><footer class="review-meta"><span class="review-avatar" aria-hidden="true">${escapeHtml(review.name.slice(0,1).toUpperCase())}</span><span class="review-name">${escapeHtml(review.name)}</span><span class="review-date"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/></svg>${escapeHtml(review.date)}</span></footer></article>`).join('')}</div><a class="servicemarket-open-link" href="https://servicemarket.com/service-provider/kashif-irshad" target="_blank" rel="noopener noreferrer">View the original ServiceMarket profile ${svgArrow}</a></div></section>`}function aboutPage(){return `${pageHero('A move is personal. Our approach should be too.','Meet the people and principles behind a more considered moving experience.','About Us')}<main class="section"><div class="container"><div class="intro-grid"><div class="image-stack"><img src="${images.team}" alt="A mover unloading furniture from a moving truck"><div class="image-quote">Good things start with how you arrive.<small>Our point of view</small></div></div><div class="split-copy"><div class="eyebrow">Our story</div><h2>People make the move.</h2><p>KI Movers exists to make moving feel more human. Behind every checklist is a real life in transition: a family starting somewhere new, a team finding its next rhythm, or a home waiting to take shape.</p><p>We bring structure to the practical details and warmth to the experience. We listen first, communicate clearly and build a plan that reflects the move in front of us.</p><div class="check-list"><span>Care with intention</span><span>Clarity at each step</span><span>Respect for your time</span><span>Room for what matters</span></div><a class="btn dark" href="/quote">Start a conversation ${svgArrow}</a></div></div></div></main>${reviewsSection()}<section class="cta-band"><div class="container"><div><h2>Let’s make a good move.</h2><p>Tell us where you’re headed and what matters to you.</p></div><a class="btn dark" href="/quote">Plan your move ${svgArrow}</a></div></section>`}
function servicesPage(){return `${pageHero('The right help for the next chapter.','Explore moving, packing and relocation support for homes, workplaces and everything in between.','Services')}<main class="section services-section"><div class="container"><div class="service-grid">${services.map((s,i)=>serviceCard(s,i)).join('')}</div></div></main><section class="cta-band"><div class="container"><div><h2>Not sure what you need?</h2><p>Share a few details and we’ll help you find the right fit.</p></div><a class="btn dark" href="/quote">Talk through your move ${svgArrow}</a></div></section>`}
function servicePage(slug){const s=services.find(x=>x[0]===slug);if(!s)return null;const title=s[1], photo=slug.includes('office')||slug.includes('commercial')||slug.includes('warehouse')?images.office:slug.includes('packing')?images.pack:slug.includes('truck')?images.truck:images.home;return `${pageHero(`${title}, with a little more care.` ,s[2]+' We plan the details around your property, timing and priorities.',`<a href="/services">Services</a> / ${title}`)}<main class="section"><div class="container service-detail-grid"><div><img class="detail-image" src="${photo}" alt="${title} in Dubai"><div class="content-prose"><h2>A plan that fits your move.</h2><p>Every move starts with understanding the place you’re leaving, the place you’re going and the things you want handled with care. We listen to your priorities and build a practical plan around them.</p><p>From preparation and packing to transport and settling in, our ${title.toLowerCase()} support is designed to keep the experience clear, considered and personal. We’ll talk through access, timing and any special requirements before moving day.</p><h2>What you can expect</h2><p>A helpful point of contact, a clear outline of the work, and practical support tailored to your move. Share what matters most and we can discuss suitable options together.</p><h2>A few thoughtful steps</h2><p>We begin with your requirements, confirm the details and coordinate a moving plan. On the day, the agreed team follows that plan and keeps communication open through the transition.</p></div></div><aside class="detail-aside"><h3>Make space for the next chapter.</h3><p>Tell us about your ${title.toLowerCase()} and we’ll help shape a plan that suits you.</p><ul><li>Discuss your timing and locations</li><li>Plan for access and special items</li><li>Choose the support that suits your move</li><li>Confirm the scope before booking</li></ul><a class="btn dark" href="/quote?service=${encodeURIComponent(title)}">Request a moving plan ${svgArrow}</a><h3 style="margin-top:34px">You may also need</h3><div class="footer-links">${services.filter(x=>x[0]!==slug).slice(0,4).map(x=>`<a href="${servicePath(x)}">${x[1]} ${svgArrow}</a>`).join('')}</div></aside></div></main><section class="section"><div class="container faq-grid"><div class="faq-intro"><div class="eyebrow">A few useful answers</div><h2>Questions about your move.</h2><p>We can talk through the details that shape your plan.</p><a class="text-link" href="/contact">Ask us directly ${svgArrow}</a></div><div class="faq-list">${faqMarkup()}</div></div></section><section class="section testimonial-section"><div class="container"><div class="service-quote"><div class="service-quote-mark" aria-hidden="true">“</div><div>${reviewStars(reviews[0].rating)}</div><blockquote>${escapeHtml(reviews[0].comment)}</blockquote><div class="service-quote-by"><b>${escapeHtml(reviews[0].name)}</b><span>Local Move · ServiceMarket</span></div><a class="text-link" href="/about#reviews">Read all customer reviews ${svgArrow}</a></div></div></section><section class="cta-band"><div class="container"><div><h2>Let’s plan your ${title.toLowerCase()}.</h2><p>Start with a few details. We’ll take it from there.</p></div><a class="btn dark" href="/quote?service=${encodeURIComponent(title)}">Request a quote ${svgArrow}</a></div></section>`}
function areasPage(){return `${pageHero('Wherever home is next.','Moving across Dubai or to another part of the UAE? Share your route and we’ll confirm what’s possible.','Areas We Serve')}<main class="section areas-section"><div class="container"><div class="section-head"><div><div class="eyebrow">Our service locations</div><h2>Across the Emirates.</h2></div><p>Local knowledge helps the details fall into place. Explore the locations below or tell us where you’re headed.</p></div><div class="areas-list" style="grid-template-columns:repeat(3,1fr)">${areas.map(a=>`<a href="${areaPath(a)}">${a}<span>↗</span></a>`).join('')}</div></div></main><section class="cta-band"><div class="container"><div><h2>Planning a move?</h2><p>We’ll help you explore the route and the details.</p></div><a class="btn dark" href="/quote">Tell us about it ${svgArrow}</a></div></section>`}
function areaPage(slug){const area=areas.find(a=>areaSlug(a)===slug);if(!area)return null;return `${pageHero(`Moving to or from ${area}.`,'Thoughtful planning for your next move, with the details of your neighbourhood in mind.',`<a href="/areas">Areas</a> / ${area}`)}<main class="section"><div class="container service-detail-grid"><div class="content-prose"><div class="eyebrow">Local moving support</div><h2>A move planned around your area.</h2><p>Every Dubai neighbourhood has its own pace, access and moving-day details. Whether you’re arriving in ${area} or heading somewhere new, we’ll talk through the route, building access, timing and any requirements that could shape your plan.</p><p>Share your locations and preferred date with us. We’ll help you consider the practical steps, from lift reservations and permits to the kind of packing support that makes sense for your home.</p><h2>Moving services in ${area}</h2><p>Our services can support apartment, house, villa and office moves, furniture transport, packing and storage enquiries. Tell us what you need and we can discuss an approach that suits your transition.</p><a class="btn dark" href="/quote">Request a ${area} moving plan ${svgArrow}</a></div><aside class="detail-aside"><h3>Thinking about moving?</h3><p>We’re happy to hear what you have in mind and help you work through the details.</p><ul><li>Share your move dates</li><li>Tell us about building access</li><li>Highlight special items or requests</li></ul><a class="btn dark" href="/quote">Get a moving quote ${svgArrow}</a><h3 style="margin-top:32px">Nearby locations</h3><div class="footer-links">${areas.filter(a=>a!==area).slice(0,5).map(a=>`<a href="${areaPath(a)}">Movers in ${a}</a>`).join('')}</div></aside></div></main><section class="cta-band"><div class="container"><div><h2>Make your next move feel simpler.</h2><p>Tell us where you’re starting and where you’re going.</p></div><a class="btn dark" href="/quote">Plan your move ${svgArrow}</a></div></section>`}
function galleryPage(){return `${pageHero('A closer look at the moving journey.','A few scenes from the care, preparation and fresh starts that shape a move.','Gallery')}<main class="section gallery"><div class="container"><div class="gallery-page-grid">${galleryItems()}</div></div></main>`}
function blogPage(){return `${pageHero('Notes for a smoother move.','Practical ideas, useful checklists and little reminders for the transition ahead.','Journal')}<main class="section"><div class="container blog-grid">${posts.map((p,i)=>`<a class="blog-card" href="/blog/${p[0]}"><img src="${[images.pack,images.boxes,images.apartment][i]}" alt="${p[1]}" loading="lazy"><div><small>${p[3]} · 4 min read</small><h3>${p[1]}</h3><p>${p[2]}</p><span class="text-link">Read the note ${svgArrow}</span></div></a>`).join('')}</div></main>`}
function postPage(slug){const p=posts.find(x=>x[0]===slug);if(!p)return null;return `${pageHero(p[1],p[2],`<a href="/blog">Journal</a> / ${p[3]}`)}<main class="section"><article class="container content-prose"><img class="detail-image" style="margin-bottom:32px" src="${images.pack}" alt="Moving day preparation"><p>${p[2]} The most useful place to begin is with a clear picture of what is happening, what needs extra attention and what would help you feel settled at the other end.</p><h2>Start with the essentials</h2><p>Write down your moving date, both addresses and any access details you already know. Check whether your building requires a permit, a service lift reservation or specific moving hours. A little coordination early can make the day feel much more straightforward.</p><h2>Give yourself room to prepare</h2><p>Set aside the items you’ll want close at hand and note anything fragile or unusually large. If you’re working with a moving team, share these details in advance so the plan reflects what matters most to you.</p><h2>Keep the plan flexible</h2><p>Every move is different. Choose the level of support that suits your home, schedule and priorities, and leave space for the unexpected details that make a new place yours.</p><a class="btn dark" href="/quote">Plan your move ${svgArrow}</a></article></main>`}
function quotePage(){return `${pageHero('Let’s start with the details.','Tell us a little about the move you have in mind. Your request is saved on this website and the team can follow up using the contact details you provide.','Get a Quote')}<main class="section page-content"><div class="container"><form class="form-wrap" id="quote-form" novalidate><div class="quote-progress"><span class="active"></span><span></span><span></span><span></span></div><div class="form-step active" data-step="0"><h2>What kind of move?</h2><p>Start with the kind of help you’re looking for.</p><div class="fields"><div class="field full"><label for="service">Service *</label><select id="service" name="service" required><option value="">Choose a service</option>${['House Moving','Apartment Moving','Villa Moving','Office Relocation','Furniture Moving','Storage','International Moving','Other'].map(s=>`<option>${s}</option>`).join('')}</select></div><div class="field full"><label for="size">Property size</label><select id="size" name="size"><option value="">Choose a size</option>${['Studio','1 BHK','2 BHK','3 BHK','Villa','Office','Other'].map(s=>`<option>${s}</option>`).join('')}</select></div></div></div><div class="form-step" data-step="1"><h2>Where are you moving?</h2><p>These details help us understand the route and timing.</p><div class="fields"><div class="field"><label for="from">Moving from *</label><input id="from" name="from" autocomplete="street-address" required placeholder="Area or address"></div><div class="field"><label for="to">Moving to *</label><input id="to" name="to" required placeholder="Area or address"></div><div class="field"><label for="date">Preferred moving date *</label><input id="date" name="date" type="date" required></div><div class="field"><label for="extras">Additional services</label><select id="extras" name="extras"><option value="">Choose if needed</option><option>Packing and unpacking</option><option>Furniture dismantling</option><option>Storage</option><option>Other</option></select></div></div></div><div class="form-step" data-step="2"><h2>Who should we contact?</h2><p>We’ll use these details to follow up about your move.</p><div class="fields"><div class="field"><label for="name">Full name *</label><input id="name" name="name" autocomplete="name" required></div><div class="field"><label for="phone">Phone number *</label><input id="phone" name="phone" type="tel" autocomplete="tel" required placeholder="Include country code"></div><div class="field"><label for="whatsapp">WhatsApp number</label><input id="whatsapp" name="whatsapp" type="tel" placeholder="If different from phone"></div><div class="field"><label for="email">Email *</label><input id="email" name="email" type="email" autocomplete="email" required></div><div class="field full"><label for="comments">Additional comments</label><textarea id="comments" name="comments" placeholder="Anything else we should know?"></textarea></div></div></div><div class="form-step" data-step="3"><h2>Review your request</h2><p>Check your details before sending your moving enquiry.</p><div class="summary-box" id="quote-summary"></div><label style="display:flex;gap:9px;align-items:start;font-size:11px;margin-top:17px"><input type="checkbox" name="consent" required> I agree that my information may be used to respond to this enquiry.</label></div><div class="form-error" aria-live="polite"></div><div class="form-controls"><button type="button" class="btn outline" id="quote-back" style="visibility:hidden">Back</button><button type="button" class="btn dark" id="quote-next">Continue ${svgArrow}</button><button type="submit" class="btn dark" id="quote-submit" style="display:none">Send request ${svgArrow}</button></div><div id="quote-status" aria-live="polite"></div></form></div></main>`}
function contactPage(){return `${pageHero('A real conversation makes a good start.','Questions, a special request or not quite sure where to begin? Send us a note and we’ll get back to you.','Contact')}<main class="section"><div class="container contact-grid"><aside class="contact-card"><div class="eyebrow" style="color:var(--lime)">Get in touch</div><h2>We’re here to help you think it through.</h2><p>Reach out using the form or the contact details provided by your moving team.</p><div class="contact-line">Phone<br><br>${biz.phoneLink?`<a href="tel:${biz.phoneLink}">${biz.phone}</a>`:biz.phone}</div><div class="contact-line">Email<br><br>${biz.email.includes('[')?biz.email:`<a href="mailto:${biz.email}">${biz.email}</a>`}</div><div class="contact-line">Location<br><br>${biz.address}</div></aside><form class="form-wrap contact-form" id="contact-form"><div class="fields"><div class="field"><label for="c-name">Full name *</label><input id="c-name" name="name" required autocomplete="name"></div><div class="field"><label for="c-phone">Phone number *</label><input id="c-phone" name="phone" required type="tel"></div><div class="field full"><label for="c-email">Email *</label><input id="c-email" name="email" required type="email"></div><div class="field full"><label for="c-message">How can we help? *</label><textarea id="c-message" name="message" required></textarea></div></div><div class="form-error" aria-live="polite"></div><button type="submit" class="btn dark">Send your message ${svgArrow}</button><div id="contact-status" aria-live="polite"></div></form></div></main>`}
function legalPage(kind){const privacy=kind==='privacy';return `${pageHero(privacy?'Privacy, handled with care.':'Clear terms for a good start.',privacy?'A straightforward overview of how enquiry information is used on this website.':'Please review these general website terms before using this site.','Legal')}<main class="section"><article class="container content-prose"><p><strong>Last updated: October 2026</strong></p>${privacy?`<h2>Information you provide</h2><p>When you send a quote or contact request, this website stores the information you submit so it can be used to respond to your enquiry. Please do not include sensitive personal information in the form.</p><h2>How information is used</h2><p>Information provided through the forms is used to understand and respond to your request. It is not sent to an external booking platform by this demonstration site.</p><h2>Data storage and requests</h2><p>Submissions are stored on the website server. For questions about a request or deletion, contact the company using its verified contact details once configured.</p><h2>Cookies and analytics</h2><p>This site does not currently set analytics or advertising cookies. This section should be updated if additional services are added.</p>`:`<h2>Website information</h2><p>Content on this website is provided for general information. Service details and availability should be confirmed directly before a booking is made.</p><h2>Quotes and bookings</h2><p>Sending an enquiry does not confirm a booking or a final price. Any scope, timing and price should be agreed in writing with the company.</p><h2>Accuracy</h2><p>Company details, service coverage and credentials should be verified before relying on them. Placeholder business information on this site must be replaced before launch.</p><h2>Contact</h2><p>Use the contact page to send a question about these terms.</p>`}</article></main>`}
function notFound(){return `<main class="not-found"><strong>404</strong><h1>This page has taken a different turn.</h1><p>Let’s get you back on the right road.</p><a class="btn dark" href="/">Return home ${svgArrow}</a></main>`}

function setMeta(title,description,path){document.title=title;document.querySelector('meta[name="description"]').content=description;document.querySelector('link[rel="canonical"]').href=`${biz.website}${path}`;document.querySelector('meta[property="og:title"]').content=title;document.querySelector('meta[property="og:description"]').content=description;document.getElementById('structured-data').textContent=JSON.stringify({"@context":"https://schema.org","@type":"MovingCompany",name:biz.name,url:biz.website,telephone:biz.phoneLink||undefined,email:biz.email.includes('[')?undefined:biz.email,address:{"@type":"PostalAddress",addressLocality:"Dubai",addressCountry:"AE"},areaServed:["Dubai","Abu Dhabi","Sharjah","Ajman","Ras Al Khaimah","Fujairah"],hasOfferCatalog:{"@type":"OfferCatalog",name:"Moving and relocation services",itemListElement:services.map(s=>({"@type":"Offer",itemOffered:{"@type":"Service",name:s[1],url:`${biz.website}${servicePath(s)}`}}))}});}
function bindPageMotion(){const items=[...app.querySelectorAll('.service-card,.step,.review-card,.faq-item,.image-stack,.why-photo,.gallery-grid button,.page-intro,.hero-copy')];items.forEach((item,index)=>item.style.setProperty('--motion-delay',`${(index%6)*28}ms`));if(!('IntersectionObserver'in window)){items.forEach(item=>item.classList.add('motion-in'));return}const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('motion-in');observer.unobserve(entry.target)}}),{rootMargin:'0px 0px -36px 0px',threshold:.08});items.forEach(item=>observer.observe(item))}
function hidePageLoader(){const loader=document.querySelector('.site-loader');if(!loader||loader.dataset.done)return;loader.dataset.done='true';setTimeout(()=>{loader.classList.add('done');setTimeout(()=>loader.remove(),340)},220)}function mount(){const path=decodeURI(location.pathname).replace(/\/$/,'')||'/';document.body.classList.toggle('quote-page',path==='/quote');const seg=path.split('/').filter(Boolean);let body, title=`${biz.name} | Movers and Packers in Dubai`, desc='Thoughtful home, villa and office moving in Dubai and across the UAE.';
if(path==='/')body=home();else if(path==='/about'){body=aboutPage();title=`About | ${biz.name}`}else if(path==='/services'){body=servicesPage();title=`Moving Services in Dubai | ${biz.name}`}else if(seg[0]==='services'&&seg[1]){body=servicePage(seg[1]);title=`${services.find(x=>x[0]===seg[1])?.[1]||'Moving'} in Dubai | ${biz.name}`}else if(path==='/areas'){body=areasPage();title=`Areas We Serve | ${biz.name}`}else if(seg[0]==='areas'&&seg[1]){body=areaPage(seg[1]);title=`Movers in ${areas.find(a=>areaSlug(a)===seg[1])||'Dubai'} | ${biz.name}`}else if(path==='/gallery'){body=galleryPage();title=`Moving Gallery | ${biz.name}`}else if(path==='/blog'){body=blogPage();title=`Moving Journal | ${biz.name}`}else if(seg[0]==='blog'&&seg[1]){body=postPage(seg[1]);title=`${posts.find(x=>x[0]===seg[1])?.[1]||'Moving Journal'} | ${biz.name}`}else if(path==='/quote'){body=quotePage();title=`Get a Moving Quote | ${biz.name}`}else if(path==='/contact'){body=contactPage();title=`Contact | ${biz.name}`}else if(path==='/privacy'){body=legalPage('privacy');title=`Privacy | ${biz.name}`}else if(path==='/terms'){body=legalPage('terms');title=`Terms | ${biz.name}`}else body=notFound();
app.innerHTML=header()+body+footer();app.classList.remove('route-enter');void app.offsetWidth;app.classList.add('route-enter');setMeta(title,desc,path);bind();bindPageMotion();hidePageLoader();}
function transitionMount(){if(typeof document.startViewTransition==='function')return document.startViewTransition(()=>mount()).updateCallbackDone;mount();return Promise.resolve()}
function bindThemeToggle(){const toggle=document.querySelector('.theme-toggle');if(!toggle)return;const root=document.documentElement;const apply=theme=>{const night=theme==='dark';root.dataset.theme=night?'dark':'light';toggle.setAttribute('aria-label',night?'Switch to day mode':'Switch to night mode');toggle.setAttribute('aria-pressed',String(night));toggle.title=night?'Switch to day mode':'Switch to night mode';toggle.classList.toggle('is-night',night);const meta=document.querySelector('meta[name=theme-color]');if(meta)meta.content=night?'#071521':'#f7fafc'};toggle.addEventListener('click',()=>apply(root.dataset.theme==='dark'?'light':'dark'));apply(root.dataset.theme||'light')}
function bind(){bindThemeToggle();document.querySelector('.hamb')?.addEventListener('click',e=>{const nav=document.querySelector('.nav-links'),open=nav.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open));e.currentTarget.textContent=open?'×':'☰'});window.onscroll=()=>{document.querySelector('.header')?.classList.toggle('scrolled',scrollY>8);document.querySelector('.back-top')?.classList.toggle('show',scrollY>500)};document.querySelector('.back-top')?.addEventListener('click',()=>scrollTo({top:0,behavior:'smooth'}));document.querySelectorAll('.faq-q').forEach(b=>b.addEventListener('click',()=>{const item=b.closest('.faq-item'),open=item.classList.toggle('open');b.setAttribute('aria-expanded',String(open));b.querySelector('b').textContent=open?'−':'＋'}));document.querySelectorAll('[data-lightbox]').forEach(b=>b.addEventListener('click',()=>{const l=document.querySelector('.lightbox');l.querySelector('img').src=b.dataset.lightbox;l.classList.add('open')}));const lightbox=document.querySelector('.lightbox');lightbox?.querySelector('button')?.addEventListener('click',()=>lightbox.classList.remove('open'));lightbox?.addEventListener('click',e=>{if(e.target===lightbox)lightbox.classList.remove('open')});bindQuote();bindContact();}
function bindQuote(){const form=document.querySelector('#quote-form');if(!form)return;const steps=[...form.querySelectorAll('.form-step')],progress=[...form.querySelectorAll('.quote-progress span')],back=form.querySelector('#quote-back'),next=form.querySelector('#quote-next'),submit=form.querySelector('#quote-submit'),error=form.querySelector('.form-error');let current=0;const refresh=()=>{steps.forEach((s,i)=>s.classList.toggle('active',i===current));progress.forEach((s,i)=>s.classList.toggle('active',i<=current));back.style.visibility=current?'visible':'hidden';next.style.display=current<3?'inline-flex':'none';submit.style.display=current===3?'inline-flex':'none';error.textContent='';if(current===3)form.querySelector('#quote-summary').textContent=[['Service',form.service.value],['Property size',form.size.value||'Not specified'],['Moving from',form.from.value],['Moving to',form.to.value],['Preferred date',form.date.value],['Additional services',form.extras.value||'None'],['Name',form.name.value],['Phone',form.phone.value],['WhatsApp',form.whatsapp.value||'Same as phone'],['Email',form.email.value],['Comments',form.comments.value||'None']].map(x=>`${x[0]}: ${x[1]}`).join('\n')};const check=()=>{const fields=[...steps[current].querySelectorAll('[required]:not([type=checkbox])')];for(const el of fields){if(!el.checkValidity()){error.textContent=el.type==='email'?'Enter a valid email address.':'Please complete the required fields before continuing.';el.focus();return false}}return true};next.onclick=()=>{if(check()){current++;refresh()}};back.onclick=()=>{current=Math.max(0,current-1);refresh()};form.querySelector('input[type=date]').min=new Date().toISOString().slice(0,10);const requested=new URLSearchParams(location.search).get('service');if(requested){const opt=[...form.service.options].find(o=>o.value.toLowerCase().includes(requested.toLowerCase().split(' ')[0]));if(opt)form.service.value=opt.value}form.onsubmit=async e=>{e.preventDefault();if(!form.reportValidity())return;submit.disabled=true;submit.textContent='Sending…';error.textContent='';const data=Object.fromEntries(new FormData(form));delete data.consent;try{const response=await fetch('/api/quote',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(data)}),result=await response.json();if(!response.ok)throw new Error(result.error||'Unable to send your request.');form.innerHTML=`<div class="form-status"><strong>Thank you — your request has been saved.</strong><br>Your enquiry reference is ${escapeHtml(result.id.slice(0,8))}. The moving team can follow up using the contact details you provided.</div>`}catch(err){submit.disabled=false;submit.innerHTML=`Send request ${svgArrow}`;error.textContent=`${err.message} Please try again.`}};}
function bindContact(){const form=document.querySelector('#contact-form');if(!form)return;form.onsubmit=async e=>{e.preventDefault();const status=form.querySelector('#contact-status'),btn=form.querySelector('button[type=submit]');status.innerHTML='';if(!form.reportValidity())return;btn.disabled=true;btn.textContent='Sending…';try{const response=await fetch('/api/contact',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(form)))}),result=await response.json();if(!response.ok)throw new Error(result.error||'Unable to send your message.');status.innerHTML=`<div class="form-status">Thanks, your message is saved. Reference: ${escapeHtml(result.id.slice(0,8))}</div>`;form.reset()}catch(err){status.innerHTML=`<div class="form-status error">${escapeHtml(err.message)} Please try again.</div>`}finally{btn.disabled=false;btn.innerHTML=`Send your message ${svgArrow}`}}}
function destinationFor(path){if(path==='/')return null;if(path==='/about')return '.intro-grid';if(path==='/services')return '.services-section .service-grid';if(path.startsWith('/services/'))return '.service-detail-grid';if(path==='/areas')return '.areas-section .section-head';if(path.startsWith('/areas/'))return '.service-detail-grid';if(path==='/gallery')return '.gallery-page-grid';if(path==='/blog')return '.blog-grid';if(path.startsWith('/blog/'))return 'article.content-prose';if(path==='/quote')return '#quote-form';if(path==='/contact')return '.contact-grid';if(path==='/privacy'||path==='/terms')return 'article.content-prose';return '.not-found'}function scrollToDestination(selector,behavior='instant'){if(!selector){window.scrollTo({top:0,behavior});return}const target=document.querySelector(selector);if(!target){window.scrollTo({top:0,behavior});return}const headerHeight=document.querySelector('.header')?.getBoundingClientRect().height||0;const top=target.getBoundingClientRect().top+window.scrollY-headerHeight-12;window.scrollTo({top:Math.max(0,top),behavior})}document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a)return;const url=new URL(a.href,location.href);if(url.origin===location.origin&&a.target!=='_blank'&&!a.hasAttribute('download')){e.preventDefault();const previousPath=location.pathname;history.pushState({},'',url.pathname+url.search+url.hash);if(url.hash){if(previousPath===url.pathname){document.querySelector(url.hash)?.scrollIntoView({behavior:'smooth'});return}transitionMount().then(()=>requestAnimationFrame(()=>document.querySelector(url.hash)?.scrollIntoView({behavior:'smooth'})));return}transitionMount().then(()=>requestAnimationFrame(()=>scrollToDestination(destinationFor(url.pathname))))}});window.addEventListener('popstate',()=>{transitionMount().then(()=>requestAnimationFrame(()=>location.hash?document.querySelector(location.hash)?.scrollIntoView({behavior:'smooth'}):scrollToDestination(destinationFor(location.pathname))))});mount();
